import type {PluginManifest, FlagSpec, ArgSpec} from '../core/types.js'
import {mkdir, writeFile} from 'node:fs/promises'
import {join, dirname} from 'node:path'

/**
 * Generate oclif command JS files from manifests.
 * Each manifest command becomes a file at:
 *   outputDir/<namespace>/<topic>/<action>.js
 *
 * The generated files use globalThis.__unionCliExecutor
 * which is set by the init hook.
 */
export async function generateCommands(manifests: PluginManifest[], outputDir: string): Promise<string[]> {
  const generated: string[] = []

  for (const manifest of manifests) {
    // pagination 활성된 manifest 의 GET 명령에 --all flag 자동 주입
    // (manifest 작성자가 매번 쓰지 않아도 됨)
    const httpCfg = manifest.provider?.config as {pagination?: unknown} | undefined
    const paginationActive = httpCfg?.pagination !== undefined

    // namespace 별 topic stub 파일 — `<bin> <ns> --help` 가 매니페스트 description 을 보여주도록
    const topicStubPath = join(outputDir, manifest.namespace, 'index.js')
    const topicStub = `// Generated by union-cli codegen — DO NOT EDIT
// Topic stub for namespace "${manifest.namespace}"
import {Command} from '@oclif/core'
export default class ${toClassName(manifest.namespace)}Topic extends Command {
  static description = ${JSON.stringify(manifest.description ?? manifest.namespace)}
  static hidden = false
  async run() {
    this.log(${JSON.stringify(manifest.description ?? manifest.namespace)})
    this.log('')
    this.log('이 namespace 의 사용 가능한 명령:')
    this.log(\`  $ \${this.config.bin} \${${JSON.stringify(manifest.namespace)}} --help\`)
  }
}
`
    await mkdir(dirname(topicStubPath), {recursive: true})
    await writeFile(topicStubPath, topicStub, 'utf-8')
    // topic stub 자체는 generated 목록에 포함하지 않음 (oclif 가 topic 으로 인식)

    for (const cmd of manifest.commands) {
      let filePath: string
      let className: string
      if (cmd.id.includes(':')) {
        const [topic, action] = cmd.id.split(':')
        filePath = join(outputDir, manifest.namespace, topic, `${action}.js`)
        className = toClassName(manifest.namespace, topic, action)
      } else {
        filePath = join(outputDir, manifest.namespace, `${cmd.id}.js`)
        className = toClassName(manifest.namespace, cmd.id)
      }

      const fullId = `${manifest.namespace}:${cmd.id}`
      const isGet = (cmd.http?.method ?? '').toUpperCase() === 'GET'
      const code = generateCommandFile(className, fullId, cmd.description, cmd.args ?? [], cmd.flags ?? [], cmd.examples ?? [], {
        dangerous: cmd.dangerous,
        successMessage: cmd.successMessage,
        httpMethod: cmd.http?.method,
        injectAllFlag: paginationActive && isGet,
      })

      await mkdir(dirname(filePath), {recursive: true})
      await writeFile(filePath, code, 'utf-8')
      generated.push(filePath)
    }
  }

  return generated
}

function toClassName(ns: string, topicOrId?: string, action?: string): string {
  const toPascal = (s: string) => s.split('-').map(p => p.charAt(0).toUpperCase() + p.slice(1)).join('')
  if (!topicOrId) return toPascal(ns)
  return action
    ? toPascal(ns) + toPascal(topicOrId) + toPascal(action)
    : toPascal(ns) + toPascal(topicOrId)
}

interface CommandOptions {
  dangerous?: boolean
  successMessage?: string
  httpMethod?: string
  /** pagination 활성 + GET 메서드 일 때 --all flag 자동 추가 */
  injectAllFlag?: boolean
}

function generateCommandFile(
  className: string,
  specId: string,
  description: string,
  args: ArgSpec[],
  flags: FlagSpec[],
  examples: string[],
  options: CommandOptions = {},
): string {
  const flagDefs = generateFlagDefs(flags)
  const argDefs = generateArgDefs(args)
  const exampleLines = examples.map(e => `    '${e.replace(/'/g, "\\'").trim()}'`).join(',\n')
  const isDangerous = options.dangerous ?? false
  const successMessage = options.successMessage
  const httpMethod = options.httpMethod
  const injectAll = options.injectAllFlag ?? false

  const dangerousImport = isDangerous ? `\nimport {createInterface} from 'node:readline'` : ''

  return `// Generated by union-cli codegen — DO NOT EDIT
import {Command, Flags, Args} from '@oclif/core'
import YAML from 'yaml'
import {writeWithPager} from 'union-cli/dist/core/pager.js'${dangerousImport}

export default class ${className} extends Command {
  static description = ${JSON.stringify(description)}
${exampleLines ? `  static examples = [\n${exampleLines},\n  ]` : ''}

${argDefs ? `  static args = {\n${argDefs}\n  }` : ''}

  static flags = {
    json: Flags.boolean({description: 'JSON 출력'}),
    debug: Flags.boolean({description: '디버그 출력'}),
    quiet: Flags.boolean({char: 'q', description: '최소 출력 (성공 메시지/spinner 등)'}),
    'silent-message': Flags.boolean({description: '성공/완료 메시지(stderr) 만 끄기 (--quiet 보다 약함)'}),
    'no-color': Flags.boolean({description: '색상/이모지 비활성화'}),
    'no-pager': Flags.boolean({description: 'pager (less) 비활성화 — 항상 stdout 직접 출력'}),
    format: Flags.string({description: '출력 형식', options: ['table', 'json', 'yaml', 'csv']}),
${injectAll ? `    all: Flags.boolean({description: '모든 페이지 누적 (pagination 활성 명령 전용)'}),\n` : ''}${isDangerous ? `    force: Flags.boolean({char: 'f', description: '확인 없이 강제 실행'}),\n` : ''}${flagDefs}  }

  async run() {
    const {args, flags} = await this.parse(${className})
    const executor = globalThis.__unionCliExecutor
    if (!executor) {
      this.error('Executor not initialized. Run "build" first.')
      return
    }
${isDangerous ? `
    // 위험한 동작: 확인 프롬프트 (TTY && !force)
    if (!flags.force) {
      if (!process.stdin.isTTY) {
        this.error('이 명령은 확인이 필요합니다. --force 플래그를 사용하세요.', {exit: 2})
        return
      }
      const rl = createInterface({input: process.stdin, output: process.stderr})
      const answer = await new Promise(r => rl.question('정말 실행하시겠습니까? (y/N): ', r))
      rl.close()
      if (answer !== 'y' && answer !== 'Y') {
        this.logToStderr('취소되었습니다.')
        return
      }
    }
` : ''}
    // Spinner: TTY && !quiet 일 때만 표시
    const showSpinner = !flags.quiet && process.stderr.isTTY
    const frames = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏']
    let spinnerIdx = 0
    const spinner = showSpinner ? setInterval(() => {
      process.stderr.write(\`\\r\${frames[spinnerIdx++ % frames.length]} 요청 중...\`)
    }, 80) : null

    const result = await executor.execute(${JSON.stringify(specId)}, {
      args,
      flags,
      raw: this.argv,
    })

    if (spinner) { clearInterval(spinner); process.stderr.write('\\r\\x1b[K') }

    if (!result.success) {
      // server-side detail 은 5xx/4xx 모두에서 자동 노출 (--debug 없이도)
      // → 사용자가 --debug 없이도 무엇이 잘못됐는지 알 수 있음
      if (result.error?.details !== undefined) {
        const det = result.error.details
        const formatted = typeof det === 'object' && det !== null ? JSON.stringify(det, null, 2) : String(det)
        this.logToStderr(formatted)
      }
      this.error(result.error?.message ?? 'Command failed', {exit: result.exitCode})
      return
    }
${successMessage ? `
    // 성공 메시지 (stderr) — --quiet 또는 --silent-message 면 끔
    if (!flags.quiet && !flags['silent-message']) {
      let msg = ${JSON.stringify(successMessage)}
      msg = msg.replace(/\\{(\\w+)\\}/g, (_, k) => String(args[k] ?? flags[k] ?? k))
      this.logToStderr(msg)
    }
` : (httpMethod && httpMethod !== 'GET' ? `
    // 상태 변경 성공 알림 (stderr)
    if (!flags.quiet && !flags['silent-message'] && process.stderr.isTTY) {
      this.logToStderr(\`${httpMethod} 요청 완료 (\${result.duration.toFixed(0)}ms)\`)
    }
` : '')}
    const rawData = result.data
    const fmt = flags.json ? 'json' : (flags.format ?? 'table')

    // --json 명시는 quiet 보다 우선 — 자동화 사용 시 quiet+json 조합도 body 출력해야 함
    if (flags.quiet && !flags.json) return

    // API 응답에서 배열 데이터 추출: {data: [...]}, {items: [...]}, 또는 직접 배열
    function extractRows(d) {
      if (Array.isArray(d)) return d
      if (d && typeof d === 'object') {
        if ('data' in d && Array.isArray(d.data)) return d.data
        if ('items' in d && Array.isArray(d.items)) return d.items
      }
      return null
    }

    // 출력은 일단 버퍼로 모은 뒤, json 이 아니고 pager 가 활성이면 less 로 파이프.
    // json 은 raw 보존 (jq 파이프) — 항상 stdout 직접.
    const __out = []
    const __log = (s) => { __out.push(String(s)) }

    switch (fmt) {
      case 'json':
        __log(JSON.stringify(rawData, null, 2))
        break
      case 'yaml':
        __log(YAML.stringify(rawData))
        break
      case 'csv': {
        const rows = extractRows(rawData) ?? [rawData]
        if (rows.length === 0) break
        // 객체/배열 셀은 한 줄 JSON 으로 직렬화 (csv/table 공통)
        function cellStrCsv(v) {
          if (v === null || v === undefined) return ''
          if (typeof v === 'object') return JSON.stringify(v)
          return String(v)
        }
        const keys = Object.keys(rows[0])
        __log(keys.join(','))
        for (const row of rows) {
          __log(keys.map(k => {
            const v = cellStrCsv(row[k])
            return v.includes(',') || v.includes('"') || v.includes('\\n') ? '"' + v.replace(/"/g, '""') + '"' : v
          }).join(','))
        }
        break
      }
      default: {
        // 문자열 또는 문자열 배열은 직접 출력
        if (typeof rawData === 'string') {
          __log(rawData)
          break
        }
        if (Array.isArray(rawData) && rawData.length > 0 && typeof rawData[0] === 'string') {
          for (const line of rawData) __log(String(line))
          break
        }

        // 한글/CJK 문자의 터미널 display width 계산
        function strWidth(s) {
          let w = 0
          for (const ch of s) {
            const cp = ch.codePointAt(0)
            w += (cp >= 0x1100 && (
              cp <= 0x115F || cp === 0x2329 || cp === 0x232A ||
              (cp >= 0x2E80 && cp <= 0x3247) ||
              (cp >= 0x3250 && cp <= 0x4DBF) ||
              (cp >= 0x4E00 && cp <= 0xA4C6) ||
              (cp >= 0xA960 && cp <= 0xA97C) ||
              (cp >= 0xAC00 && cp <= 0xD7A3) ||
              (cp >= 0xF900 && cp <= 0xFAFF) ||
              (cp >= 0xFE10 && cp <= 0xFE19) ||
              (cp >= 0xFE30 && cp <= 0xFE6B) ||
              (cp >= 0xFF01 && cp <= 0xFF60) ||
              (cp >= 0xFFE0 && cp <= 0xFFE6) ||
              (cp >= 0x1F000 && cp <= 0x1FBFF) ||
              (cp >= 0x20000 && cp <= 0x3FFFF)
            )) ? 2 : 1
          }
          return w
        }
        function padEnd(s, width) {
          return s + ' '.repeat(Math.max(0, width - strWidth(s)))
        }

        const rows = extractRows(rawData)
        if (!rows || rows.length === 0) {
          __log(JSON.stringify(rawData, null, 2))
          break
        }
        // 객체/배열은 한 줄 JSON 으로 직렬화 (그냥 String() 하면 [object Object])
        function cellStr(v) {
          if (v === null || v === undefined) return ''
          if (typeof v === 'object') return JSON.stringify(v)
          return String(v)
        }
        const keys = Object.keys(rows[0])
        const widths = keys.map(k => Math.max(k.length, ...rows.map(r => strWidth(cellStr(r[k])))))
        __log(keys.map((k, i) => padEnd(k.toUpperCase(), widths[i])).join('  '))
        __log(widths.map(w => '-'.repeat(w)).join('  '))
        for (const row of rows) {
          __log(keys.map((k, i) => padEnd(cellStr(row[k]), widths[i])).join('  '))
        }
        break
      }
    }

    // flush — json 은 jq 파이프 친화로 raw 출력. 그 외는 TTY+긴 출력 시 less 자동.
    const __text = __out.join('\\n') + '\\n'
    if (fmt === 'json' || flags['no-pager']) {
      process.stdout.write(__text)
    } else {
      await writeWithPager(__text)
    }
  }
}
`
}

function generateFlagDefs(flags: FlagSpec[]): string {
  return flags.map(f => {
    const opts: string[] = []
    if (f.description) opts.push(`description: ${JSON.stringify(f.description)}`)
    if (f.char) opts.push(`char: ${JSON.stringify(f.char)}`)
    if (f.required) opts.push(`required: true`)
    if (f.options) opts.push(`options: ${JSON.stringify(f.options)}`)

    const flagName = f.name.includes('-') ? `'${f.name}'` : f.name

    if (f.type === 'boolean') {
      return `    ${flagName}: Flags.boolean({${opts.join(', ')}}),`
    } else if (f.type === 'number') {
      if (f.default !== undefined) opts.push(`default: ${f.default}`)
      opts.push(`parse: async (input) => { const n = Number(input); if (Number.isNaN(n)) throw new Error(\`Expected a number but received: \${input}\`); return n }`)
      return `    ${flagName}: Flags.custom({${opts.join(', ')}})(),`
    } else {
      if (f.default !== undefined) opts.push(`default: ${JSON.stringify(f.default)}`)
      return `    ${flagName}: Flags.string({${opts.join(', ')}}),`
    }
  }).join('\n')
}

function generateArgDefs(args: ArgSpec[]): string {
  if (args.length === 0) return ''
  return args.map(a => {
    const opts: string[] = []
    if (a.description) opts.push(`description: ${JSON.stringify(a.description)}`)
    if (a.required) opts.push(`required: true`)
    if (a.default !== undefined) opts.push(`default: ${JSON.stringify(a.default)}`)
    return `    ${a.name}: Args.string({${opts.join(', ')}}),`
  }).join('\n')
}
